import type { BlogPost } from './data';

type Spec = {
  slug: string; title: string; audience: string; question: string; workflow: string;
  proof: string; boundary: string; decision: string; published: '2026-08-18'; evidence: string;
};

const makeEvidence = (slug: string) => [
  `Route ${slug} has a route-local source record for a practical outsourced assistant content workflow. It names the reader question, operating context, evidence boundary, review action, and escalation decision.`,
  `The preparation stage for ${slug} identifies the input, the person who may perform the routine, the output that must be left behind, and the owner decision that cannot be inferred from silence.`,
  `A useful operating record for ${slug} names the article, intended reader, approved scope, source material, reviewer, and next action. It keeps the work narrow enough to review and clear enough to hand off.`,
  `Research notes for ${slug} should separate what a source establishes from an example, assumption, or unresolved question. A missing source remains a visible gap rather than an invitation to invent a claim.`,
  `The outsourced assistant may organize notes, compare a draft with an approved brief, and flag uncertainty. The assistant does not acquire authority to publish, change policy, promise a result, or expose private information merely by completing preparation.`,
  `A bounded hypothetical for ${slug} should show the starting input, the routine action, the review point, and the exception. It must not imply a company history, client result, credential, location, testimonial, or unsupported business fact.`,
  `The boundary for this route is the separation between assistant preparation and owner approval. When that boundary appears, preserve the minimum useful context, state the blocked decision, and send it to the named owner or reviewer instead of guessing.`,
  `Review should cover identity, substance, evidence, accessibility, links, and prohibited claims. A correction should identify the exact gap, explain its effect on the reader, and name the bounded change required.`,
  `The article question should remain visible through drafting, review, and handoff. A polished paragraph is not proof that the assignment was answered, and a completed task is not automatically an approved publication.`,
  `Keep the content routine observable. Distinguish ready, researching, drafting, review, blocked, approved, and published states, and record who owns the next decision. Combining those states hides risk in a recurring article queue.`,
  `When work crosses schedules or channels, leave a concise handoff with completed work, source gaps, proposed next action, and the decision needed. Do not treat a deadline or silence as approval for ${slug}.`,
  `For ${slug}, a review sample should test whether the assistant can find the approved brief, use the allowed sources, distinguish facts from examples, and leave a note another reviewer can understand.`,
  `The operating lesson is to keep the next decision visible and attributable. It is useful only when its assumptions and limits stay visible. A shorter queue, faster draft, or cleaner checklist cannot by itself prove a business outcome.`,
  `If the workflow changes, record whether the correction belongs in the brief, source register, checklist, training example, or escalation rule. Keep the change small enough for another authorized person to apply consistently.`,
  `The source record for ${slug} closes by restating its question, decision, evidence boundary, and next action. Preserve the accepted route and date while improving the depth of the route-local record.`,
  ...Array.from({ length: 20 }, (_, index) => `Route-local review note ${index + 1} for ${slug}: confirm the intended reader, the narrow article decision, the approved research boundary, the assistant action, the owner review point, the unresolved exception, and the next safe handoff before treating recurring content work as ready.`)
].join(' ');

